target = ".......((((.((((.(((.(((....))).(((.(((....))).(((.(((....))).(((.(((....))).(((......))).))).))).))).))).(....).)))).((((...(((.(((...((....))........))).(((.(((....)))(((....)))(((....)))))).)))...((((.(....).(((.(((.(((.(((.(((...(((....))).))).(((....))).))).(((....))).))).(((....))).))).((((((....)))(((....))).(((....)))))).))).))))...)))).))))......."
n = len(target)
def fold(s): return RNA.fold_compound(s).mfe()[0]
def worker(seed):
    random.seed(seed)
    # build template start
    pairs=[]
    stack=[]
    for i,c in enumerate(target):
        if c=='(': stack.append(i)
        elif c==')': j=stack.pop(); pairs.append((j,i))
    pm={}
    for i,j in pairs: pm[i]=j; pm[j]=i
    for attempt in range(60):
        # random WC init with some GC bias
        seq=['A']*n
        for i,j in pairs:
            p=random.choice([('G','C'),('C','G'),('G','C'),('A','U'),('U','A'),('G','U')])
            seq[i]=p[0]; seq[j]=p[1]
        start=''.join(seq)
        s,d = RNA.inverse_fold(start, target)
        if d==0 and fold(s)==target:
            return s
    return None
if __name__=='__main__':
    t0=time.time()
    with mp.Pool(64) as p:
        for r in p.imap_unordered(worker, range(512)):
            if r:
                print("SOLVED", r, "t", round(time.time()-t0,1))
                p.terminate(); break
    print("done", round(time.time()-t0,1))
